"use client"

import CheckIcon from "@/components/icons/CheckIcon"
import CautionIcon from "@/components/icons/ErrorIcon"
import DeleteIcon from "@/components/icons/DeleteIcon"
import ErrorIcon from "@/components/icons/ErrorIcon"

type Props = {
  icon: React.ReactNode
  value: string
  onChange: (v: string) => void
  placeholder?: string
  onRemove: () => void
  isValid?: boolean
}

export default function RemovableLinkInput({
  icon,
  value,
  onChange,
  placeholder = "",
  onRemove,
  isValid = false,
}: Props) {
  const showStatus = value.trim().length > 0

  return (
    <div className="w-[426px] h-[40px] flex items-center gap-[13px]">
      {/* Media Icon */}
      <div className="w-[24px] h-[24px] flex items-center justify-center">
        {icon}
      </div>

      {/* Input Field */}
      <div className="relative w-[360px] h-[40px]">
        <input
          value={value}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder}
          className="
            w-full h-full
            px-[10px] py-[12px]
            border border-[#A5A5A5]/50
            rounded-[8px]
            text-[12px] font-inter text-[#262626]
            placeholder:text-[#A5A5A5]
            outline-none bg-white
          "
        />

        {/* Status icon inside input */}
        {showStatus && (
          <div className="absolute right-[10px] top-1/2 -translate-y-1/2">
            {isValid ? (
              <div className="scale-[0.78]">
                <CheckIcon className="[&_path]:stroke-[#00CF07]" />
              </div>
            ) : (
              <div className="text-[#FF4603]">
                <ErrorIcon />
              </div>
            )}
          </div>
        )}
      </div>

      {/* Delete (outside input) */}
      <button
        type="button"
        onClick={onRemove}
        className="w-[9px] h-[9px] flex items-center justify-center text-[#A5A5A5]"
        aria-label="Remove link"
      >
        <DeleteIcon />
      </button>
    </div>
  )
}
